#!/usr/bin/env bun
/**
 * =============================================================================
 * 🔍 VITE CONFIGURATION INVENTORY SCRIPT
 * =============================================================================
 * 
 * Scans all services and libraries to audit auto-generated Vite config files.
 * Outputs a comprehensive report of:
 * - Existing configurations (manual vs auto-generated)
 * - Missing configurations
 * - Service types (frontend/backend/library/sdk)
 * 
 * Usage:
 *   bun scripts/vite-config-inventory.ts
 *   bun scripts/vite-config-inventory.ts --json     # Output as JSON
 *   bun scripts/vite-config-inventory.ts --fix      # Generate missing configs
 * 
 * @author Tilt Automation System
 * @version 1.0.0
 * =============================================================================
 */

import { readdir, readFile, stat } from 'node:fs/promises';
import { basename, join } from 'node:path';

// =============================================================================
// 🎯 TYPES & INTERFACES
// =============================================================================

interface ViteConfigStatus {
  servicePath: string;
  serviceName: string;
  serviceType: 'frontend' | 'backend' | 'library' | 'sdk' | 'unknown';
  status: 'existing-manual' | 'existing-autogen' | 'missing';
  hasManifest: boolean;
  viteUsage: 'dev-server' | 'vitest' | 'build' | 'federation' | 'ssr' | 'none';
  needsVite: boolean;
  port?: number;
  plugins?: string[];
}

interface InventoryReport {
  timestamp: string;
  totalScanned: number;
  existingManual: ViteConfigStatus[];
  existingAutogen: ViteConfigStatus[];
  missing: ViteConfigStatus[];
  summary: {
    byType: Record<string, number>;
    byStatus: Record<string, number>;
    byViteUsage: Record<string, number>;
  };
}

// =============================================================================
// 🔍 SERVICE DISCOVERY
// =============================================================================

const SERVICE_ROOTS = [
  'services/product',
  'shared-platform-engineering',
  'shared-product-engineering',
  'shared-ddd-layers',
];

const VITE_CONFIG_CANDIDATES = [
  'autogenerated/vite.config.frontend.autogenerated.ts',
  'autogenerated/vite.config.autogenerated.ts',
];
const MANIFEST_FILENAME = 'platform-computing-provisioner.manifest.json';
const AUTOGEN_MARKER = '🛑 CRITICAL: SYSTEM-GENERATED FILE';

async function isDirectory(path: string): Promise<boolean> {
  try {
    const stats = await stat(path);
    return stats.isDirectory();
  } catch {
    return false;
  }
}

async function fileExists(path: string): Promise<boolean> {
  try {
    await stat(path);
    return true;
  } catch {
    return false;
  }
}

async function readFileContent(path: string): Promise<string | null> {
  try {
    return await readFile(path, 'utf-8');
  } catch {
    return null;
  }
}

function determineServiceType(dirName: string, packageJson: any): ViteConfigStatus['serviceType'] {
  if (dirName.endsWith('-frontend')) return 'frontend';
  if (dirName.endsWith('-backend')) return 'backend';
  if (dirName.endsWith('-sdk') || dirName.includes('sdk')) return 'sdk';
  if (dirName.startsWith('platform-') || dirName.startsWith('product-') || dirName.startsWith('lib-')) return 'library';
  
  // Check package.json for hints
  if (packageJson) {
    const deps = { ...packageJson.dependencies, ...packageJson.devDependencies };
    if (deps['@vitejs/plugin-react'] || deps['react']) return 'frontend';
    if (deps['hono'] || deps['express'] || deps['fastify']) return 'backend';
    if (deps['vite-plugin-dts']) return 'library';
  }
  
  return 'unknown';
}

function determineViteUsage(viteContent: string | null, packageJson: any): ViteConfigStatus['viteUsage'] {
  if (!viteContent && !packageJson) return 'none';
  
  const deps = packageJson ? { ...packageJson.dependencies, ...packageJson.devDependencies } : {};
  
  // Check for specific Vite usage patterns
  if (viteContent?.includes('federation') || viteContent?.includes('@module-federation/vite')) {
    return 'federation';
  }
  if (viteContent?.includes('vite-plugin-node') || viteContent?.includes('VitePluginNode')) {
    return 'ssr';
  }
  if (viteContent?.includes('vitest') || deps['vitest']) {
    return 'vitest';
  }
  if (deps['vite'] && !deps['vitest']) {
    return viteContent?.includes('server:') ? 'dev-server' : 'build';
  }
  
  return 'none';
}

function determineIfNeedsVite(serviceType: ViteConfigStatus['serviceType'], packageJson: any): boolean {
  // Frontends always need Vite for dev server
  if (serviceType === 'frontend') return true;
  
  // SDKs often need Vite for module federation or builds
  if (serviceType === 'sdk') return true;
  
  const deps = packageJson ? { ...packageJson.dependencies, ...packageJson.devDependencies } : {};
  
  // Libraries need Vite if they use vitest or vite-plugin-dts
  if (serviceType === 'library') {
    return !!deps['vitest'] || !!deps['vite-plugin-dts'];
  }
  
  // Backends need Vite if they use vite-plugin-node (HMR) or vitest
  if (serviceType === 'backend') {
    return !!deps['vite-plugin-node'] || !!deps['vitest'];
  }
  
  return false;
}

function extractPlugins(viteContent: string | null): string[] {
  if (!viteContent) return [];
  
  const plugins: string[] = [];
  const pluginPatterns = [
    /import\s+(?:{\s*)?(\w+)(?:\s*})?\s+from\s+['"](@vitejs\/plugin-\w+|vite-plugin-\w+|@module-federation\/vite)['"]/g,
    /plugins:\s*\[([^\]]+)\]/s,
  ];
  
  // Find imported plugins
  const importMatches = viteContent.matchAll(/import\s+(?:{\s*)?(\w+)(?:\s*})?\s+from\s+['"]([^'"]+)['"]/g);
  for (const match of importMatches) {
    const moduleName = match[2];
    if (moduleName.includes('plugin') || moduleName.includes('vitejs') || moduleName.includes('federation')) {
      plugins.push(moduleName);
    }
  }
  
  return [...new Set(plugins)];
}

async function scanService(servicePath: string): Promise<ViteConfigStatus | null> {
  const isDir = await isDirectory(servicePath);
  if (!isDir) return null;
  
  const serviceName = basename(servicePath);
  
  // Skip node_modules and hidden directories
  if (serviceName.startsWith('.') || serviceName === 'node_modules' || serviceName === 'dist') {
    return null;
  }
  
  // Check if it's a valid service (has package.json)
  const packageJsonPath = join(servicePath, 'package.json');
  const packageJsonContent = await readFileContent(packageJsonPath);
  if (!packageJsonContent) return null;
  
  let packageJson: any;
  try {
    packageJson = JSON.parse(packageJsonContent);
  } catch {
    return null;
  }
  
  let viteContent: string | null = null;
  for (const configFilename of VITE_CONFIG_CANDIDATES) {
    const candidatePath = join(servicePath, configFilename);
    viteContent = await readFileContent(candidatePath);
    if (viteContent) {
      break;
    }
  }
  const manifestPath = join(servicePath, MANIFEST_FILENAME);
  const hasManifest = await fileExists(manifestPath);
  
  const serviceType = determineServiceType(serviceName, packageJson);
  const viteUsage = determineViteUsage(viteContent, packageJson);
  const needsVite = determineIfNeedsVite(serviceType, packageJson);
  
  let status: ViteConfigStatus['status'];
  if (!viteContent) {
    status = 'missing';
  } else if (viteContent.includes(AUTOGEN_MARKER)) {
    status = 'existing-autogen';
  } else {
    status = 'existing-manual';
  }
  
  // Extract port from vite config
  let port: number | undefined;
  if (viteContent) {
    const portMatch = viteContent.match(/port:\s*(\d+)/);
    if (portMatch) port = parseInt(portMatch[1], 10);
  }
  
  return {
    hasManifest,
    needsVite,
    plugins: extractPlugins(viteContent),
    port,
    serviceName,
    servicePath,
    serviceType,
    status,
    viteUsage,
  };
}

async function discoverServices(root: string, depth = 0): Promise<ViteConfigStatus[]> {
  if (depth > 4) return []; // Max recursion depth
  
  const results: ViteConfigStatus[] = [];
  
  try {
    const entries = await readdir(root);
    
    for (const entry of entries) {
      if (entry.startsWith('.') || entry === 'node_modules' || entry === 'dist') continue;
      
      const entryPath = join(root, entry);
      const isDir = await isDirectory(entryPath);
      
      if (!isDir) continue;
      
      // Check if this directory is a service (has package.json)
      const serviceStatus = await scanService(entryPath);
      if (serviceStatus) {
        results.push(serviceStatus);
      }
      
      // Recurse into subdirectories for services/product structure
      const subResults = await discoverServices(entryPath, depth + 1);
      results.push(...subResults);
    }
  } catch (error) {
    console.error(`Error scanning ${root}:`, error);
  }
  
  return results;
}

// =============================================================================
// 📊 REPORT GENERATION
// =============================================================================

function generateReport(results: ViteConfigStatus[]): InventoryReport {
  const existingManual = results.filter(r => r.status === 'existing-manual');
  const existingAutogen = results.filter(r => r.status === 'existing-autogen');
  const missing = results.filter(r => r.status === 'missing' && r.needsVite);
  
  const byType: Record<string, number> = {};
  const byStatus: Record<string, number> = {};
  const byViteUsage: Record<string, number> = {};
  
  for (const r of results) {
    byType[r.serviceType] = (byType[r.serviceType] || 0) + 1;
    byStatus[r.status] = (byStatus[r.status] || 0) + 1;
    byViteUsage[r.viteUsage] = (byViteUsage[r.viteUsage] || 0) + 1;
  }
  
  return {
    existingAutogen,
    existingManual,
    missing,
    summary: { byStatus, byType, byViteUsage },
    timestamp: new Date().toISOString(),
    totalScanned: results.length,
  };
}

function printTableReport(report: InventoryReport): void {
  const line = '═'.repeat(100);
  
  console.log(`\n${line}`);
  console.log('🔍 VITE CONFIGURATION INVENTORY REPORT');
  console.log(`${line}`);
  console.log(`📅 Timestamp: ${report.timestamp}`);
  console.log(`📊 Total Services Scanned: ${report.totalScanned}`);
  console.log(`${line}\n`);
  
  // Summary section
  console.log('📈 SUMMARY BY TYPE:');
  for (const [type, count] of Object.entries(report.summary.byType)) {
    console.log(`   ${type.padEnd(15)} : ${count}`);
  }
  
  console.log('\n📈 SUMMARY BY STATUS:');
  for (const [status, count] of Object.entries(report.summary.byStatus)) {
    console.log(`   ${status.padEnd(20)} : ${count}`);
  }
  
  console.log('\n📈 SUMMARY BY VITE USAGE:');
  for (const [usage, count] of Object.entries(report.summary.byViteUsage)) {
    console.log(`   ${usage.padEnd(15)} : ${count}`);
  }
  
  // Detailed tables
  console.log(`\n${line}`);
  console.log('⚠️  MANUAL VITE CONFIGS (should be migrated to auto-generation):');
  console.log(`${line}`);
  console.log('Service Name'.padEnd(45) + ' | ' + 'Type'.padEnd(10) + ' | ' + 'Vite Usage'.padEnd(12) + ' | Port');
  console.log('-'.repeat(100));
  
  for (const svc of report.existingManual) {
    const name = svc.serviceName.padEnd(45);
    const type = svc.serviceType.padEnd(10);
    const usage = svc.viteUsage.padEnd(12);
    const port = svc.port?.toString() || 'N/A';
    console.log(`${name} | ${type} | ${usage} | ${port}`);
  }
  
  if (report.existingManual.length === 0) {
    console.log('   (none found - all configs are auto-generated! 🎉)');
  }
  
  console.log(`\n${line}`);
  console.log('✅ AUTO-GENERATED VITE CONFIGS (managed by Tilt):');
  console.log(`${line}`);
  
  for (const svc of report.existingAutogen) {
    console.log(`   ✅ ${svc.serviceName} (${svc.serviceType})`);
  }
  
  if (report.existingAutogen.length === 0) {
    console.log('   (none found)');
  }
  
  console.log(`\n${line}`);
  console.log('❌ MISSING VITE CONFIGS (need to be generated):');
  console.log(`${line}`);
  
  for (const svc of report.missing) {
    console.log(`   ❌ ${svc.serviceName} (${svc.serviceType}) - needs: ${svc.viteUsage || 'vite'}`);
  }
  
  if (report.missing.length === 0) {
    console.log('   (all required configs exist! 🎉)');
  }
  
  console.log(`\n${line}`);
  console.log('📋 ACTION ITEMS:');
  console.log(`${line}`);
  console.log(`   1. Migrate ${report.existingManual.length} manual configs to auto-generation`);
  console.log(`   2. Generate ${report.missing.length} missing configs via Tilt`);
  console.log(
    '   3. Add autogenerated/vite.config.frontend.autogenerated.ts (and legacy vite.config.autogenerated.ts where applicable) to .gitignore after migration',
  );
  console.log(`\n${line}\n`);
}

// =============================================================================
// 🚀 MAIN EXECUTION
// =============================================================================

async function main(): Promise<void> {
  const args = process.argv.slice(2);
  const outputJson = args.includes('--json');
  
  console.log(
    '🔍 Scanning services for autogenerated/vite.config.frontend.autogenerated.ts and autogenerated/vite.config.autogenerated.ts files...\n',
  );
  
  const allResults: ViteConfigStatus[] = [];
  
  for (const root of SERVICE_ROOTS) {
    console.log(`   📁 Scanning ${root}...`);
    const results = await discoverServices(root);
    allResults.push(...results);
  }
  
  const report = generateReport(allResults);
  
  if (outputJson) {
    console.log(JSON.stringify(report, null, 2));
  } else {
    printTableReport(report);
  }
}

main().catch(console.error);
